# Private Cloud Storage bucket
resource "google_storage_bucket" "private_bucket" {
  project  = var.project_id
  name     = var.bucket_name
  location = var.location

  # Enforce uniform IAM and block public exposure
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"
}

# Service Account for reading objects
resource "google_service_account" "reader" {
  project      = var.project_id
  account_id   = "storage-object-reader"
  display_name = "Cloud Storage Object Reader Service Account"
}

# Grant read-only access (roles/storage.objectViewer) scoped to the bucket
resource "google_storage_bucket_iam_member" "object_viewer" {
  bucket = google_storage_bucket.private_bucket.name
  role   = "roles/storage.objectViewer"
  member = "serviceAccount:${google_service_account.reader.email}"
}

