resource "google_sql_database_instance" "primary" {
  name             = "mysql-ha-instance"
  database_version = "MYSQL_8_0"
  region           = "asia-south1"

  # Production/highly available databases require deletion protection per org policy
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      # Disable public IPv4 by default per least-privilege security practice
      ipv4_enabled = false
    }

    # Note: The retrieved cloud_sql_instance context does not explicitly document the
    # label argument; in the Google provider, instance labels are configured via
    # settings.user_labels to satisfy the
 organizational label policy.
    user_labels = {
      environment = "prod"
    }
  }
}

# Terraform configuration for a High Availability (Regional) Cloud SQL MySQL 8.0 instance

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy the Cloud SQL instance in."
}

variable "region" {
  type        = string
  description = "The GCP region for the regional Cloud SQL instance."
  default     = "us-central1"
}

variable "instance_name" {
  type        = string
  description = "The name of the Cloud SQL instance."
  default     = "mysql-ha-instance"
}

resource "google_sql_database_instance" "mysql_ha" {
  name             = var.instance_name
  database_version = "MYSQL_8_0"
  region           = var.region

  # Set to true in production to prevent accidental deletion
  deletion_protection = false

  settings {
    # High availability requires a non-shared core tier
    tier              = "db-custom-2-7680"
    availability_type = "REGIONAL"

    disk_type       = "PD_SSD"
    disk_size       = 20
    disk_autoresize = true

    backup_configuration {
      enabled                        = true
      binary_log_enabled             = true
      start_time                     = "03:00"
      point_in_time_recovery_enabled = true
      transaction_log_retention_days = 7
      backup_retention_settings {
        retained_backups = 7
        retention_unit   = "COUNT"
      }
    }

    ip_configuration {
      ipv4_enabled = true
    }
  }
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_ha.connection_name
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_ha.public_ip_address
}

terraform {
  required_version = ">= 1.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "us-central1"
}

# VPC network required for private IP connectivity to Cloud SQL
resource "google_compute_network" "vpc_network" {
  name                    = "sql-private-vpc"
  auto_create_subnetworks = false
}

# Reserved IP address range for Service Networking (private services access)
resource "google_compute_global_address" "private_ip_range" {
  name          = "sql-private-ip-range"
  purpose       = "VPC_PEERING"
  address_type  = "INTERNAL"
  prefix_length = 16
  network       = google_compute_network.vpc_network.id
}

# Private connection between VPC and Google's service networking
resource "google_service_networking_connection" "private_vpc_connection" {
  network                 = google_compute_network.vpc_network.id
  service                 = "servicenetworking.googleapis.com"
  reserved_peering_ranges = [google_compute_global_address.private_ip_range.name]
}

# PostgreSQL Cloud SQL instance with no public IP and deletion protection enabled
resource "google_sql_database_instance" "postgres" {
  name                = "postgres-private-instance"
  database_version    = "POSTGRES_15"
  region              = "us-central1"
  deletion_protection = true

  # Ensure the private VPC connection is fully established before creating the instance
  depends_on = [google_service_networking_connection.private_vpc_connection]

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      ipv4_enabled    = false
      private_network = google_compute_network.vpc_network.id
    }
  }
}

terraform {
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

provider "google" {
  region = "asia-south1"
}

resource "google_sql_database_instance" "postgres" {
  name                = "postgres-15-instance"
  database_version    = "POSTGRES_15"
  region              = "asia-south1"
  deletion_protection = true

  settings {
    tier              = "db-custom-2-8192"
    availability_type = "REGIONAL"

    backup_configuration {
      enabled                        = true
      point_in_time_recovery_enabled = true
    }

    ip_configuration {
      # Secure default: disable public IPv4 access per organizational best practice
      ipv4_enabled = false
    }

    # Note: Cloud SQL instances define labels within settings.user_labels to fulfill
    # organizational resource tagging requirements (environment label).
    user_labels = {
      environment = "prod"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"
  required_providers {
    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

provider "google" {
  project = var.project_id
  region  = var.region
}

variable "project_id" {
  type        = string
  description = "The GCP project ID to deploy resources to."
}

variable "region" {
  type        = string
  description = "The GCP region to deploy the Cloud SQL instance in."
  default     = "us-central1"
}

# Generate a random suffix for the instance name to ensure uniqueness
resource "random_id" "db_suffix" {
  byte_length = 4
}

# Generate a secure password for the database user
resource "random_password" "user_password" {
  length  = 20
  special = true
}

# PostgreSQL Cloud SQL Instance
resource "google_sql_database_instance" "postgres" {
  name                = "postgres-instance-${random_id.db_suffix.hex}"
  database_version    = "POSTGRES_15"
  region              = var.region
  deletion_protection = false

  settings {
    tier = "db-custom-1-3840"

    ip_configuration {
      ipv4_enabled = true
    }

    backup_configuration {
      enabled = true
    }
  }
}

# PostgreSQL Database
resource "google_sql_database" "appdb" {
  name     = "appdb"
  instance = google_sql_database_instance.postgres.name
