  name         = "index.html"
  bucket       = google_storage_bucket.static_website.name
  content_type = "text/html; charset=utf-8"
  content      = <<-EOT
    <!DOCTYPE html>
    <html lang="en">
    <head>
        <meta charset="UTF-8">
        <title>Public Static Website</title>
    </head>
    <body>
        <h1>Welcome to your GCP static website!</h1>
        <p>Served directly from Google Cloud Storage.</p>
    </body>
    </html>
  EOT
}

# Example 404 error page
resource "google_storage_bucket_object" "not_found_html" {
  name         = "404.html"
  bucket       = google_storage_bucket.static_website.name
  content_type = "text/html; charset=utf-8"
