    google = {
      source  = "hashicorp/google"
      version = "~> 8.0"
    }
  }
}

variable "project_id" {
  description = "The GCP project ID to host the database."
  type        = string
}

variable "region" {
  description = "The GCP region to deploy the database in."
  type        = string
  default     = "us-central1"
}

variable "office_vpn_cidr" {
  description = "Public IP address or CIDR range of the office VPN allowed to access the Cloud SQL instance."
  type        = string
  default     = "203.0.113.50/32"
}

variable "db_password" {
  description = "Password for the Cloud SQL application user."
  type        = string
  sensitive   = true
}

provider "google" {
  project = var.project_id
  region  = var.region
}

# Cloud SQL Database Instance (MySQL 8.0)
resource "google_sql_database_instance" "mysql_instance" {
  name             = "mysql-public-instance"
  database_version = "MYSQL_8_0"
  region           = var.region

  # Set to true for production workloads to prevent accidental deletion
  deletion_protection = false

  settings {
    tier = "db-custom-2-7680"

    ip_configuration {
      # Allocate and enable a public IPv4 address
      ipv4_enabled = true

      # Restrict public access to designated office VPN IP ranges
      authorized_networks {
        name  = "office-vpn"
        value = var.office_vpn_cidr
      }
    }

    backup_configuration {
      enabled            = true
      binary_log_enabled = true
    }
  }
}

# Default application database
resource "google_sql_database" "database" {
  name     = "app_db"
  instance = google_sql_database_instance.mysql_instance.name
  charset  = "utf8mb4"
  collation = "utf8mb4_general_ci"
}

# Database user with remote access permissions from authorized networks
resource "google_sql_user" "user" {
  name     = "app_user"
  instance = google_sql_database_instance.mysql_instance.name
  host     = "%"
  password = var.db_password
}

output "public_ip_address" {
  description = "The public IPv4 address assigned to the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.public_ip_address
}

output "instance_connection_name" {
  description = "The connection name of the Cloud SQL instance."
  value       = google_sql_database_instance.mysql_instance.connection_name
}

